const facetDetails = await browserjs(tabId, () => {
  const titles = Array.from(document.querySelectorAll('.title'));
  const results = {};
  for (const t of titles) {
    const name = t.textContent.trim();
    const container = t.closest('div') || t.parentElement;
    const items = Array.from(container.querySelectorAll('li, a, label, input')).map(el => ({
      tagName: el.tagName,
      text: el.textContent.trim().replace(/\s+/g, ' '),
      href: el.href || null,
      id: el.id || null,
      type: el.type || null,
      checked: el.checked || false,
      value: el.value || null
    }));
    results[name] = items;
  }
  return results;
});

for (const [k, v] of Object.entries(facetDetails)) {
  console.log(`=== ${k} === (${v.length} items)`);
  // print first 15 items
  console.log(v.slice(0, 15));
}
"}
